import Image from "next/image";
import { forwardRef } from "react";

interface CarouselImageProps {
  src: string;
  alt: string;
  onLoad?: () => void;
  priority?: boolean;
  blurDataURL?: string;
  onClick?: () => void;
}

export const CarouselImage = forwardRef<HTMLImageElement, CarouselImageProps>(
  ({ src, alt, onLoad, priority = false, blurDataURL, onClick }, ref) => {
    const handleLoad = () => {
      onLoad?.();
    };

    return (
      <div className="relative w-full h-full flex items-center justify-center py-6">
        <div className="relative max-w-full h-full flex items-center justify-center max-h-full pb-6">
          <Image
            ref={ref}
            src={src}
            alt={alt}
            width={1200}
            height={800}
            className={`max-w-full max-h-full w-auto object-contain rounded-2xl overflow-hidden transition-all shadow-2xl border-6 md:border-8 border-neutral-500/15 duration-500 cursor-pointer hover:scale-[1.02] active:scale-[0.98]`}
            onLoad={handleLoad}
            onClick={onClick}
            priority={priority}
            placeholder={blurDataURL ? "blur" : "empty"}
            blurDataURL={blurDataURL}
            loading={priority ? "eager" : "lazy"}
            sizes="(max-width: 768px) 100vw, (max-width: 1200px) 90vw, 80vw"
          />
        </div>
      </div>
    );
  },
);

CarouselImage.displayName = "CarouselImage";

"use client";

import { useQuery, useQueryClient, useMutation } from "@tanstack/react-query";
import { useCallback } from "react";

interface UseViewCountReturn {
  viewCount: number;
  incrementView: () => Promise<void>;
  isLoading: boolean;
  error: string | null;
}

// Query key factory
const viewCountKeys = {
  all: ["viewCount"] as const,
  byId: (imageId: number) => [...viewCountKeys.all, imageId] as const,
};

// Fetch function for view count
const fetchViewCount = async (imageId: number): Promise<number> => {
  const response = await fetch(`/api/views/${encodeURIComponent(imageId)}`);

  if (!response.ok) {
    throw new Error("Failed to fetch view count");
  }

  const data = await response.json();
  return data.viewCount || 0;
};

// Increment view count function
const incrementViewCount = async (imageId: number): Promise<number> => {
  const response = await fetch("/api/views", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ imageId }),
  });

  if (!response.ok) {
    throw new Error("Failed to increment view count");
  }

  const data = await response.json();
  return data.viewCount || 0;
};

export function useViewCount(imageId: number): UseViewCountReturn {
  const queryClient = useQueryClient();

  // Query for fetching view count with 5-minute stale time
  const {
    data: viewCount = 0,
    isLoading,
    error: queryError,
  } = useQuery({
    queryKey: viewCountKeys.byId(imageId),
    queryFn: () => fetchViewCount(imageId),
    enabled: !!imageId,
    staleTime: 5 * 60 * 1000, // 5 minutes
  });

  // Mutation for incrementing view count
  const incrementMutation = useMutation({
    mutationFn: () => incrementViewCount(imageId),
    onSuccess: (newViewCount) => {
      // Update the query cache with the new view count
      queryClient.setQueryData(viewCountKeys.byId(imageId), newViewCount);
    },
    onError: () => {
      // Optimistic update on error - increment the cached value
      queryClient.setQueryData(
        viewCountKeys.byId(imageId),
        (old: number = 0) => old + 1,
      );
    },
  });

  const incrementView = useCallback(async () => {
    await incrementMutation.mutateAsync();
  }, [incrementMutation]);

  return {
    viewCount,
    incrementView,
    isLoading: isLoading || incrementMutation.isPending,
    error: queryError?.message || incrementMutation.error?.message || null,
  };
}

